dataTransform.transform:
[edges.node~>|$|(


  $sa := scheduledStartAt;
  $se := scheduledFinishAt;
  $as := actualStartAt;
  $d  := $moment().isBefore($se) ? $se : null ;
  $bal := $coalesce([balanceQuantity, 1]);
  $rat := $coalesce([standardRate, 1]);
  $set := $coalesce([setupRate, 0]);
  $rem := $isNilOrEmpty(actualStartAt) ? $sum(($bal/$rat)+setupRate) : $sum($bal/$rat);
  {
  "aheadLabel": $moment().add($rem, 'hour').diff($se) <= 0 ? "On Schedule" : null,
  "lateLabel": $moment().add($rem,'hour').diff($se) > 0 ? "Late" : null,
  "aheadColor": $moment().add($rem, 'hour').diff($se) <= 0 ? "#2be84f" : null,
  "lateColor": $moment().add($rem,'hour').diff($se) > 0 ? "#ff5656" : null,
  "process":$join(distributions.edges.node.workOrderProcess.code, "/")

}  

)|
]

